# Build final output: copy pattern to top section with direct row mapping
# Row 3 pattern -> Row 0
# Row 4 pattern -> Row 1

sep_row = 2
output = [[9]*26 for _ in range(5)]
output[sep_row] = [4]*26

# Original pattern stays
input_pattern = {
    (3,9): 8, (3,11): 8, (3,13): 6, (3,15): 8, (3,16): 7,
    (4,12): 8, (4,13): 8, (4,14): 3
}

for (r, c), v in input_pattern.items():
    output[r][c] = v

# Copy bottom pattern to top section - keeping row order from bottom
# Pattern at rows 3,4 maps to rows 0,1 (both preserve row 0 of section first)
for new_r, old_r in [(0, 3), (1, 4)]:
    for c, v in input_pattern.items():
        if c in [9,11,13,15,16,12,13,14]:  # cols in bottom-middle
            if old_r == 3 and c in [9,11,13,15,16]:
                output[new_r][c] = v
            elif old_r == 4 and c in [12,13,14]:
                output[new_r][c] = v

print("Output grid (direct copy from bottom to top):")
for i, row in enumerate(output):
    print(f"Row {i}: {' '.join(map(str, row))}")
